def valid(number: str) -> bool:
    """Return whether a card number passes the Luhn checksum."""
    digits = number.replace(' ', '')
    if len(digits) < 2 or not digits.isascii() or not digits.isdigit():
        return False

    total = 0
    for index, char in enumerate(reversed(digits)):
        digit = int(char)
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
